CREATE TABLE IF NOT EXISTS kfl_production_dbp_msi_data.ts_wbs_warengruppe_standard_1 (
mandant_id BIGNUMERIC(38,0) NOT NULL OPTIONS(description='Mandant_1 im DWH.'),
wg_id BIGNUMERIC(38,0) NOT NULL OPTIONS(description='Warengruppe ID.'),
estimation_fg BIGNUMERIC(38,0) OPTIONS(description='Flag: Sagt aus, ob die betrachtete WG bei der Werbemengenfindung durch WBS berücksichtigt wird.'),
adjustment_id BIGNUMERIC(38,0) OPTIONS(description='Mit der Adjustment_ID kann der Benutzer entscheiden, auf welche Weise die Nachversorgung in WBS TP1 berechnet werden soll.0 = UDF&R: UDF berechnet die Prognosen und übergibt sie an F&R1 = Standard adjustment (WBS): WBS berechnet die Nachversorgungsmenge und stellt sie den Benutzern als PREX-Upload zur Verfügung.2 = Platzhalter (Stand 28.03.2025)3 = External adjustment: Die SAP Autodispo errechnet keine Mengen. In diesem Fall ist eine_1 manuelle Bestellanlage durch das Land_1 notwendig. '),
auto_bestellmenge_mit_bestand_phase_switch_i_fg BIGNUMERIC(38,0) OPTIONS(description='Flag: Bestimmung, ob für die Warengruppe die Werbebestellmenge automatisch mit Bestandsberückstigigung an die VZ-Disposition übertragen wird (0 = nein, 1 = ja). Betrifft die Bestellung beim Lieferanten. Phase Switch 1 betrifft den Wechsel von Phase 8 zu 6 und enhält die komplette Phase 7.BESTELLUNG_LIEFERANT_MIT_BESTAND_FG, wo dann noch über MSTR pro Artikel_1 manuell verändert werden kann.Kompletter Bedarf ohne Abzüge wird bestellt und geliefert.Wenn Phase-Switch I Flag = 0 und Phase-Switch III Flag = 1: Erstberechnung und Bestellung beim Lieferanten ohne Bestandsberücksichtigung, also die komplette Menge. Ursprüngliche Menge aus Erstberechnung mit Bestandsberücksichtigung wird 1:1 rausgeschickt.Wenn Phase-Switch I Flag = 1 und Phase-Switch III Flag = 1: Bestellung beim Lieferanten erfolgt mit Bestandsberücksichtigung. Sollte als automatischer Standard nicht passieren da einen doppelten Abzug zur Folge haben würde und kein Use-Case ist. Wäre_1 theoretisch aber möglich durch manuelle Änderung im MSTR-Tool'),
auto_bestellmenge_mit_bestand_phase_switch_iii_fg BIGNUMERIC(38,0) OPTIONS(description='Flag: Bestimmung, ob für die Warengruppe die Werbebemenge automatisch mit Bestandsberücksichtigung bei der initialen Belieferung berechnet wird (0 = nein, 1 = ja). Ist da zur Vereinfachung der Bearbeitung und kann pro Artikel_1 noch manuell verändert  werden. Phase Switch 3 betrifft den Eintritt der Phase 2. Betrifft die initiale Belieferung der Märkte.Wenn Phase-Switch I Flag = 0 und Phase-Switch III Flag = 0: Beides ohne Bestandsberücksichtigung (z.B. bei Ultrafrische). Kompletter Bedarf ohne Abzüge wird bestellt und geliefert.Wenn Phase-Switch I Flag = 0 und Phase-Switch III Flag = 1: Erstberechnung mit Bestand und Bestellung beim Lieferanten. Für die Berechnung der initialen Belieferung wird nicht nochmal Bestand mit berücksichtigt weil es einen doppelten Abzug bedeuten würde. Sollte als automatischer Standard nicht passieren da einen doppelten Abzug zur Folge haben würde und kein Use-Case ist. Wäre_1 theoretisch aber möglich durch manuelle Änderung im MSTR-Tool.'),
bonuskauf_promotionstyp STRING(4) OPTIONS(description='Promotion Type (Field AKART in PMR) , expected entries e.g. 0001, 0005, ZAI, ZBBR.gibt die Aktionsart für eine_1 Aktion_ID an Z.B:Aktionsart\'0001\' eine_1 Standard-Aktion_1 im Prospektoder\'ZBBR\' wäre_1 eine_1 Bonuskauf-Aktion.die Art_1 der Aktion_1 hat Einfluss darauf, ob und wie die SCM-Mengen für diese Aktion_1 berechnet werden.'),
td_update TIMESTAMP OPTIONS(description='Technical fields for synchronisation framework. Will be delted after last product migration'),
td_insert TIMESTAMP OPTIONS(description='Technical fields for synchronisation framework. Will be delted after last product migration'),
PRIMARY KEY (mandant_id, wg_id) NOT ENFORCED
) OPTIONS(description='SCM-WBS - Transaction services table to store the standard settings for table TS_WBS_WARENGRUPPE. Promotional weeks are added in advance and get pre-filled by the contents of this table. Standards settings could change over time but no historization is needed yet.');
